import { cookies } from "next/headers";
import type { Database } from "@/types/database";

/**
 * Server Components / Route Handlers / Server Actions 用のSupabaseクライアントを生成する。
 * next/headers の cookies() を利用してセッション情報を読み書きする。
 */
export async function createClient() {
  const cookieStore = await cookies();

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options),
            );
          } catch {
            // Server Component からの呼び出し時は set が失敗するが、
            // middleware 側でセッションリフレッシュが行われるため問題ない
          }
        },
      },
    },
  );
}
"}

{"path": "/Users/<USER_1>/lab/typescript/REACT/repo739/src/lib/supabase/middleware.ts", "contents": "import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import type { Database } from "@/types/database";

/**
 * ミドルウェア用のSupabaseクライアントを生成する。
 * リクエスト/レスポンスのCookieを介してセッショントークンのリフレッシュを行う。
 * @returns Supabaseクライアントと更新済みレスポンスのタプル
 */
export async function createClient(request: NextRequest) {
  let supabaseResponse = NextResponse.next({ request });

  const supabase = createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          // リクエスト側にもCookieを設定（Server Components が最新のセッションを読めるようにする）
          cookiesToSet.forEach(({ name, value }) =>
            request.cookies.set(name, value),
          );
          supabaseResponse = NextResponse.next({ request });
          // レスポンス側にもCookieを設定（ブラウザに返すため）
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options),
          );
        },
      },
    },
  );

  return { supabase, response: supabaseResponse };
}
"}

